"""Independent rational accounting for the reviewed READY timing refinement."""
from decimal import Decimal
from fractions import Fraction
from math import isfinite

REPLICATES = {"development": 8192, "validation": 32768}
ROLES = ("writer", "primary", "reviewer")
def number(value):
    assert type(value) in (float, Decimal), type(value)
    assert isfinite(value) and value >= 0
    return Fraction(str(value))

def projection(bounds):
    fixed = {role: number(bounds["roles"][role]["fixed"]) for role in ROLES}
    repeat = {role: number(bounds["roles"][role]["repetitive"]) for role in ROLES}
    assert all(value > 0 for value in repeat.values())
    phases = {}
    for phase, count in REPLICATES.items():
        phases[phase] = {}
        for role in ROLES:
            seconds = 2 * (fixed[role] + count * repeat[role])
            limit = (21600 if phase == "development" else 43200) if role == "writer" else 57600
            phases[phase][role] = {"seconds": seconds, "budget_ok": seconds <= limit,
                "legacy_12h": seconds <= 43200, "prior_14h": seconds <= 50400,
                "effective_16h": seconds <= 57600}
    session = 2 * (number(bounds["control_setup"]) + sum(fixed[r] + n * repeat[r]
        for n in REPLICATES.values() for r in ROLES)
        + max(REPLICATES.values()) * number(bounds["control_residual"]))
    return {"phases": phases, "session": session,
        "eligible": session <= 295800 and all(row["budget_ok"] for p in phases.values() for row in p.values())}

def group_bounds(rows):
    assert type(rows) is list and len(rows) == 3
    return {"roles": {r: {field: max(row["roles"][r][field] for row in rows)
        for field in ("fixed", "repetitive")} for r in ROLES},
        "control_setup": max(row["control_setup"] for row in rows),
        "control_residual": max(row["control_residual"] for row in rows)}

def check_advertised(bounds, shown):
    expected = projection(bounds)
    for phase, roles in expected["phases"].items():
        for role, reference in roles.items():
            measured = shown["phases"][phase][role]
            assert abs(number(measured["projected_seconds"]) - reference["seconds"]) <= Fraction(1, 1000000)
            for flag in ("budget_ok", "legacy_12h", "prior_14h", "effective_16h"):
                assert measured[flag] is reference[flag], (phase, role, flag)
    assert abs(number(shown["session_projected_seconds"]) - expected["session"]) <= Fraction(1, 1000000)
    assert shown["session_budget_ok"] is (expected["session"] <= 295800)
    assert shown["eligible"] is expected["eligible"]
    assert shown["timing_model"] == "PARENT_READY_FIXED_ALL_POST_READY_REPEATED_2X"
    return expected
